import {
  deleteAlias, deleteIncomeSource, deletePayrollScheme, deletePayrollYear, deletePensionScheme, deleteRelationship, deleteSaRegistration, saveAlias,
  saveIncomeSource, savePayrollScheme, savePayrollYear, savePensionScheme, saveRelationship, saveSaRegistration
} from '../records/client-registers'
import { actor, result } from './session'
import { checkNotificationsSoon } from '../services/notifier'

/** A handler that changes something and replies with nothing. */
const done = (fn: () => void) => (): null => {
  fn()
  return null
}

ipcMain.handle('registers:aliases', (_e, ref: unknown) => result('registers', () => listAliases(getDb(), actor(), ref)))

// Changed from the Client file (Level 4F).
ipcMain.handle('registers:save-payroll', (_e, input: unknown) => result('registers', () => savePayrollScheme(getDb(), actor(), input)))
ipcMain.handle('registers:delete-payroll', (_e, id: unknown) => result('registers', done(() => deletePayrollScheme(getDb(), actor(), id))))
ipcMain.handle('registers:save-payroll-year', (_e, input: unknown) => result('registers', () => savePayrollYear(getDb(), actor(), input)))
ipcMain.handle('registers:delete-payroll-year', (_e, id: unknown) => result('registers', done(() => deletePayrollYear(getDb(), actor(), id))))
// A pension's duties start date moves its re-declaration deadlines, so notifications are checked again.
ipcMain.handle('registers:save-pension', (_e, input: unknown) =>
  result('registers', () => {
    const saved = savePensionScheme(getDb(), actor(), input)
    checkNotificationsSoon()
    return saved
  })
)
ipcMain.handle('registers:delete-pension', (_e, id: unknown) =>
  result('registers', () => {
    const removed = deletePensionScheme(getDb(), actor(), id)
    checkNotificationsSoon()
    return removed
  })
)
ipcMain.handle('registers:save-sa', (_e, input: unknown) => result('registers', () => saveSaRegistration(getDb(), actor(), input)))
ipcMain.handle('registers:delete-sa', (_e, id: unknown) => result('registers', done(() => deleteSaRegistration(getDb(), actor(), id))))
ipcMain.handle('registers:save-income', (_e, input: unknown) => result('registers', () => saveIncomeSource(getDb(), actor(), input)))
ipcMain.handle('registers:delete-income', (_e, id: unknown) => result('registers', done(() => deleteIncomeSource(getDb(), actor(), id))))
ipcMain.handle('registers:save-relationship', (_e, input: unknown) => result('registers', () => saveRelationship(getDb(), actor(), input)))
ipcMain.handle('registers:delete-relationship', (_e, id: unknown, clientRef: unknown) =>
  result('registers', done(() => deleteRelationship(getDb(), actor(), id, clientRef)))
)
ipcMain.handle('registers:save-alias', (_e, input: unknown) => result('registers', () => saveAlias(getDb(), actor(), input)))
ipcMain.handle('registers:delete-alias', (_e, id: unknown) => result('registers', done(() => deleteAlias(getDb(), actor(), id))))
